#!/usr/bin/env python3
"""Regenerates internal/engine/catalog_types.go: the map from each change
type to its argument struct. Run it after adding or renaming a handler:

    python3 scripts/gen-catalog.py
"""
import glob, os, re

root = os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "internal", "engine")
src = "".join(open(f).read() for f in sorted(glob.glob(os.path.join(root, "ch_*.go"))))
out = [
    "// Code generated by scripts/gen-catalog.py; run it when a handler's argument type changes.",
    "",
    "package engine",
    "",
    "// argTypes maps each change type to a zero value of its arguments, for the",
    "// catalog that describes the API to callers.",
    "var argTypes = map[string]any{",
]
for name, fn in re.findall(r'register\("([^"]+)", core\.Role\w+, (\w+)\)', src):
    m = re.search(r"func " + fn + r"\(c \*cx\) error \{\n\tvar a (\w+)", src)
    if not m:
        raise SystemExit(f"{name}: handler {fn} does not start with 'var a <ArgsType>'")
    out.append(f'\t"{name}": {m.group(1)}{{}},')
out.append("}")
open(os.path.join(root, "catalog_types.go"), "w").write("\n".join(out) + "\n")
os.system(f"gofmt -w {os.path.join(root, 'catalog_types.go')}")
print(f"{len(out) - 8} change types")
